import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

// ---- inlined from densityContours ----
/** mulberry32, seeded so the cloud is byte-identical on every reload. */
function createRandom(seed: number): () => number {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

type Eruption_densityContours = { waiting: number; eruptions: number };

type Mode = {
  waiting: number;
  eruptions: number;
  waitingSd: number;
  eruptionsSd: number;
  correlation: number;
  share: number;
};

/**
 * Old Faithful splits into a short-idle/short-burst group and a long-idle/long-burst one,
 * with a thin ridge of intermediate eruptions between them.
 */
const MODES: Mode[] = [
  { waiting: 54, eruptions: 2.02, waitingSd: 5.4, eruptionsSd: 0.26, correlation: 0.35, share: 0.34 },
  { waiting: 80, eruptions: 4.36, waitingSd: 6.1, eruptionsSd: 0.37, correlation: 0.3, share: 0.61 },
  { waiting: 68, eruptions: 3.2, waitingSd: 7.2, eruptionsSd: 0.55, correlation: 0.62, share: 0.05 }
];

const WAITING_RANGE = [41, 99] as const;
const ERUPTIONS_RANGE = [1.4, 5.4] as const;

function createEruptions(count: number, seed: number): Eruption_densityContours[] {
  const random = createRandom(seed);
  const normal = () => {
    const u = random() || Number.EPSILON; // Box-Muller diverges at exactly zero
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * random());
  };
  const points: Eruption_densityContours[] = [];
  while (points.length < count) {
    let pick = random();
    const mode = MODES.find((m) => (pick -= m.share) <= 0) ?? MODES[MODES.length - 1];
    const first = normal();
    const second = mode.correlation * first + Math.sqrt(1 - mode.correlation ** 2) * normal();
    const waiting = Math.round(mode.waiting + mode.waitingSd * first);
    const eruptions = Math.round((mode.eruptions + mode.eruptionsSd * second) * 1000) / 1000;
    const inRange =
      waiting >= WAITING_RANGE[0] &&
      waiting <= WAITING_RANGE[1] &&
      eruptions >= ERUPTIONS_RANGE[0] &&
      eruptions <= ERUPTIONS_RANGE[1];
    if (inRange) points.push({ waiting, eruptions });
  }
  return points;
}

const eruptions: Eruption_densityContours[] = createEruptions(680, 20260813);

/** One observation per point: idle minutes before the eruption, and its length in minutes. */
export type Data = { waiting: number; eruptions: number }[];

type Eruption = Data[number];

const MARGIN = { top: 16, right: 20, bottom: 36, left: 44 };
const THRESHOLD_COUNT = 26;

export default function DensityContours({
  data = eruptions,
  width
}: {
  data?: Data;
  width: number;
}) {
  const height = Math.round(width * 0.62);
  const innerWidth = Math.max(1, Math.round(width - MARGIN.left - MARGIN.right));
  const innerHeight = Math.max(1, Math.round(height - MARGIN.top - MARGIN.bottom));
  // The kernel is a pixel width, so it has to track the plot or it over-smooths when narrow.
  const bandwidth = Math.max(8, innerWidth / 26);

  const x = useMemo(
    () =>
      d3
        .scaleLinear()
        .domain(d3.extent(data, (d) => d.waiting) as [number, number])
        .nice()
        .range([0, innerWidth]),
    [data, innerWidth]
  );

  const y = useMemo(
    () =>
      d3
        .scaleLinear()
        .domain(d3.extent(data, (d) => d.eruptions) as [number, number])
        .nice()
        .range([innerHeight, 0]),
    [data, innerHeight]
  );

  const contours = useMemo(
    () =>
      d3
        .contourDensity<Eruption>()
        .x((d) => x(d.waiting))
        .y((d) => y(d.eruptions))
        .size([innerWidth, innerHeight])
        .bandwidth(bandwidth)
        .thresholds(THRESHOLD_COUNT)(data),
    [data, x, y, innerWidth, innerHeight, bandwidth]
  );

  const color = useMemo(() => {
    const peak = d3.max(contours, (c) => c.value) ?? 1;
    // Square root spreads the sparse outer bands, which linear density collapses into the background.
    return d3.scaleSequentialSqrt(d3.interpolateRgb('#22262a', '#d4a24c')).domain([0, peak]).clamp(true);
  }, [contours]);

  const path = useMemo(() => d3.geoPath(), []);

  const xTicks: Tick[] = useMemo(
    () => x.ticks(Math.max(3, Math.round(innerWidth / 90))).map((v) => ({ value: String(v), offset: x(v) })),
    [x, innerWidth]
  );

  const yTicks: Tick[] = useMemo(
    () => y.ticks(5).map((v) => ({ value: String(v), offset: y(v) })),
    [y]
  );

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Density contours of 680 Old Faithful eruptions by idle time and eruption length, showing two distinct modes"
    >
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <AxisLeft ticks={yTicks} width={innerWidth} />
        <g strokeLinejoin="round">
          {contours.map((contour, i) => (
            <path
              key={contour.value}
              d={path(contour) ?? undefined}
              fill={color(contour.value)}
              stroke="var(--bg)"
              // Every fifth band gets a heavier rule, as in the source notebook, to read as a level set.
              strokeWidth={i % 5 ? 0.3 : 0.9}
            />
          ))}
        </g>
        <g fill="var(--text)" fillOpacity={0.32}>
          {data.map((d, i) => (
            <circle key={i} cx={x(d.waiting)} cy={y(d.eruptions)} r={1.3} />
          ))}
        </g>
        {/* Drawn after the bands so the baseline stays crisp under the lowest contour. */}
        <AxisBottom ticks={xTicks} height={innerHeight} width={innerWidth} />
        <text x={innerWidth} y={innerHeight - 8} fill="var(--text)" fontSize={12} fontWeight="bold" textAnchor="end">
          Idle (min.)
        </text>
        <text x={4} y={12} fill="var(--text)" fontSize={12} fontWeight="bold">
          Erupting (min.)
        </text>
      </g>
    </svg>
  );
}
